events.body:
The GUI fee bump with an external signer still uses v2 (`WalletModel::bumpFee` -> `signBumpTransaction` -> `feebumper::SignTransaction`, pinned to v2 and shared with RPC `bumpfee`).

Suggestion: a `psbt_version` param can be added to `feebumper::SignTransaction/signBumpTransaction`, with the GUI passing 0 and RPC keeping 2.


<details>
<summary>diff</summary>

```diff
diff --git a/src/interfaces/wallet.h b/src/interfaces/wallet.h
index 8862f94fab..da140f721e 100644
--- a/src/interfaces/wallet.h
+++ b/src/interfaces/wallet.h
@@ -175,7 +175,7 @@ public:
         CMutableTransaction& mtx) = 0;
 
     //! Sign bump transaction.
-    virtual bool signBumpTransaction(CMutableTransaction& mtx) = 0;
+    virtual bool signBumpTransaction(CMutableTransaction& mtx, uint32_t psbt_version) = 0;
 
     //! Commit bump transaction.
     virtual bool commitBumpTransaction(const Txid& txid,
diff --git a/src/qt/walletmodel.cpp b/src/qt/walletmodel.cpp
index 2422b88579..95454e2265 100644
--- a/src/qt/walletmodel.cpp
+++ b/src/qt/walletmodel.cpp
@@ -524,7 +524,7 @@ bool WalletModel::bumpFee(Txid hash, Txid& new_hash)
     assert(!m_wallet->privateKeysDisabled() || wallet().hasExternalSigner());
 
     // sign bumped transaction
-    if (!m_wallet->signBumpTransaction(mtx)) {
+    if (!m_wallet->signBumpTransaction(mtx, /*psbt_version=*/0)) {
         QMessageBox::critical(nullptr, tr("Fee bump error"), tr("Can't sign transaction."));
         return false;
     }
diff --git a/src/wallet/feebumper.cpp b/src/wallet/feebumper.cpp
index ab64fd8cda..1c7288aedd 100644
--- a/src/wallet/feebumper.cpp
+++ b/src/wallet/feebumper.cpp
@@ -336,13 +336,12 @@ Result CreateRateBumpTransaction(CWallet& wallet, const Txid& txid, const CCoinC
     return Result::OK;
 }
 
-bool SignTransaction(CWallet& wallet, CMutableTransaction& mtx) {
+bool SignTransaction(CWallet& wallet, CMutableTransaction& mtx, uint32_t psbt_version) {
     LOCK(wallet.cs_wallet);
 
     if (wallet.IsWalletFlagSet(WALLET_FLAG_EXTERNAL_SIGNER)) {
-        // Make a blank PSBT, this means that users will need to have an
-        // external signer software that supports BIP-0370.
-        PartiallySignedTransaction psbtx(mtx, /*version=*/2);
+        // Make a blank psbt
+        PartiallySignedTransaction psbtx(mtx, psbt_version);
 
         // First fill transaction with our data without signing,
         // so external signers are not asked to sign more than once.
diff --git a/src/wallet/feebumper.h b/src/wallet/feebumper.h
index 4e0befe412..62faea52af 100644
--- a/src/wallet/feebumper.h
+++ b/src/wallet/feebumper.h
@@ -58,9 +58,10 @@ Result CreateRateBumpTransaction(CWallet& wallet,
     std::optional<uint32_t> original_change_index = std::nullopt);
 
 //! Sign the new transaction,
+//! @param psbt_version PSBT version passed to an external signer, if the wallet uses one
 //! @return false if the tx couldn't be found or if it was
 //! impossible to create the signature(s)
-bool SignTransaction(CWallet& wallet, CMutableTransaction& mtx);
+bool SignTransaction(CWallet& wallet, CMutableTransaction& mtx, uint32_t psbt_version);
 
 //! Commit the bumpfee transaction.
 //! @return success in case of CWallet::CommitTransaction was successful,
diff --git a/src/wallet/interfaces.cpp b/src/wallet/interfaces.cpp
index a7d24ca0b9..3a70e88c3a 100644
--- a/src/wallet/interfaces.cpp
+++ b/src/wallet/interfaces.cpp
@@ -300,7 +300,7 @@ public:
         std::vector<CTxOut> outputs; // just an empty list of new recipients for now
         return feebumper::CreateRateBumpTransaction(*m_wallet.get(), txid, coin_control, errors, old_fee, new_fee, mtx, /* require_mine= */ true, outputs) == feebumper::Result::OK;
     }
-    bool signBumpTransaction(CMutableTransaction& mtx) override { return feebumper::SignTransaction(*m_wallet.get(), mtx); }
+    bool signBumpTransaction(CMutableTransaction& mtx, uint32_t psbt_version) override { return feebumper::SignTransaction(*m_wallet.get(), mtx, psbt_version); }
     bool commitBumpTransaction(const Txid& txid,
         CMutableTransaction&& mtx,
         std::vector<bilingual_str>& errors,
diff --git a/src/wallet/rpc/spend.cpp b/src/wallet/rpc/spend.cpp
index e228298c0c..9de3464675 100644
--- a/src/wallet/rpc/spend.cpp
+++ b/src/wallet/rpc/spend.cpp
@@ -1138,7 +1138,8 @@ static RPCMethod bumpfee_helper(std::string method_name)
     // For bumpfee, return the new transaction id.
     // For psbtbumpfee, return the base64-encoded unsigned PSBT of the new transaction.
     if (!want_psbt) {
-        if (!feebumper::SignTransaction(*pwallet, mtx)) {
+        // External signers must support BIP-0370 (PSBT v2)
+        if (!feebumper::SignTransaction(*pwallet, mtx, /*psbt_version=*/2)) {
             if (pwallet->IsWalletFlagSet(WALLET_FLAG_EXTERNAL_SIGNER)) {
                 throw JSONRPCError(RPC_WALLET_ERROR, "Transaction incomplete. Try psbtbumpfee instead.");
             }
```

</details>

